INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('91fa2274459af62a2000','Amedex 2023.pdf','21','Mixed/Unclassified','A 47-year-old man has developed central chest pain one hour ago. On examination in the Emergency Department he is sweating profusely,
has a BP of 90/60 mmHg and a pulse rate of 50bpm. An ECG shows 2-mm ST elevation in leads II, III, and aVF. Which one of the following is
the most common cause of death in pre-hospital setting in this condition?','{"A":"Ventricular tachycardia.","B":"Ventricular fibrillation.","C":"Bradycardia.","D":"Asystole.","E":"Hypotension."}','B','The clinical and ECG findings are characteristic of inferior ST-elevation myocardial infarction (STEMI).
Of all patients experiencing acute myocardial infarction (MI), usually in the form of ST-elevation MI, 25–35% will die of sudden cardiac death
(SCD) before receiving medical attention, most often from ventricular fibrillation; however, ventricular tachycardia is the most common
arrhythmia early in the course of MI.
Patients suspected of having STEMI should be connected to defibrillator on the way to the hospital. Most ventricular fibrillations occur in the
first 24 hour post-MI, with a half occurring within the first hour.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"230","duplicate_group_id":"exact-5945a06b151b","duplicate_sources":[{"record_id":"91fa2274459af62a2000","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":21,"source_qid":"230"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"91fa2274459af62a2000","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":21,"source_qid":"230","domain_hint":"Mixed/Unclassified","stem":"A 47-year-old man has developed central chest pain one hour ago. On examination in the Emergency Department he is sweating profusely,\nhas a BP of 90/60 mmHg and a pulse rate of 50bpm. An ECG shows 2-mm ST elevation in leads II, III, and aVF. Which one of the following is\nthe most common cause of death in pre-hospital setting in this condition?","options":{"A":"Ventricular tachycardia.","B":"Ventricular fibrillation.","C":"Bradycardia.","D":"Asystole.","E":"Hypotension."},"source_answer":"B","source_explanation":"The clinical and ECG findings are characteristic of inferior ST-elevation myocardial infarction (STEMI).\nOf all patients experiencing acute myocardial infarction (MI), usually in the form of ST-elevation MI, 25–35% will die of sudden cardiac death\n(SCD) before receiving medical attention, most often from ventricular fibrillation; however, ventricular tachycardia is the most common\narrhythmia early in the course of MI.\nPatients suspected of having STEMI should be connected to defibrillator on the way to the hospital. Most ventricular fibrillations occur i