INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('7ee3efe3e27f906ca791','src-v294-687f312c','249','39','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 62-year-old woman is seen in the ward 24 hours after a non-ST segment elevation myocardial infarction (NSTEMI). She complains of light-
headedness. The radial pulse is difficult to feel, blood pressure is 90/60 mmHg, heart sounds are muffled, and there is evidence of
biventricular cardiac failure. Which one of the following rhythm strips would be of most concern in this situation?',NULL,'A','The clinical picture of weak pulses, tachycardia and lightheadedness are suggestive of a tachyarrhythmia of ventricular origin, i.e. ventricular
tachycardia (VT) or ventricular fibrillation (VF). The latter is always associated with loss of consciousness; therefore, cannot be considered in
this woman.
The only rhythm strip consistent with the clinical picture is option A, which shows VT. VT is the most common arrhythmia occuring after
myocardial infarction (MI). They are in particular common in the first 24 hours post-MI.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,'https://drive.google.com/thumbnail?id=1jIxpmB1Z6d92Y6ekH4zzyIl8NrRYL1JJ&sz=w1600','2023','v2.9.4',1,'source_page_image','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[39],"source_qid":"249","duplicate_group_id":"exact-f098c55edc31","duplicate_sources":[{"record_id":"7ee3efe3e27f906ca791","record_type":"visual_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":39,"source_qid":"249"}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v282_visual_page_asset","text_method":"source_page_image+best_available_text","visual_asset":"visual_assets/Amedex_2023__73a208604f57/page_00039.jpg","asset_preview_url":"https://drive.google.com/file/d/1jIxpmB1Z6d92Y6ekH4zzyIl8NrRYL1JJ/preview"}',NULL,'needs_verification','[]','low') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
