INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8df547e12bf2e9b1b0a9','Amedex 2023.pdf','50','Mixed/Unclassified','A 72-year-old man is brought to emergency department with ambulance after he sustained a sudden severe chest pain radiating to his back.
On auscultation there is a diastolic murmur best heard over the left sternal border in the second intercostal space. ECG shows ST elevation in
leads II, III and aVF. A CXR is remarkable for a widened mediastinum. Which one of the following is the most appropriate management?','{"A":"Give alteplase.","B":"Give aspirin, intravenous morphine, and beta blockers.","C":"Give morphine and beta blockers and arrange for emergency trans-esophageal sonography.","D":"Refer the patient to cardiology clinic.","E":"Arrange for emergency angiography."}','C','The clinical findings of abrupt chest pain radiating to back and a widened mediastinum on CXR are consistent with diagnosis aortic
dissection. The diastolic murmur signifies involvement of the proximal aorta resulting in aortic regurgitation and decreased blood flow to the
coronary arteries and a consequent myocardial infarction (MI). Thrombolytics (e.g. alteplase) (option A) are absolutely contraindicated when
aortic dissection is suspected.
Aspirin (option B), clopidogrel and other anticoagulation medications are contraindicated as well due to increased risk of deterioration of the
dissection, which is temporarily stable. The cornerstone of initial therapy in this situation is morphine for pain control (and its partial effect on
lowering blood pressure) and beta blockers to maintain the systolic blood pressure below 120 mmHg. Trans-esophageal sonography should
be emergently performed to confirm the diagnosis.Angiography using CT angiogram (CTA) (option E) is the preferred method if trans-
esophageal sonography is not available.
(Option C) Referring the patient to a cardiology clinic while he is in the hopsital and in urgent need for intervention is not an appropriate
option.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"261","duplicate_group_id":"exact-75439fdf216e","duplicate_sources":[{"record_id":"8df547e12bf2e9b1b0a9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":50,"source_qid":"261"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"8df547e12bf2e9b1b0a9","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":50,"source_qid":"261","domain_hint":"Mixed/Unclassified","stem":"A 72-year-old man is brought to emergency department with ambulance after he sustained a sudden severe chest pain radiating to his back.\nOn auscultation there is a diastolic murmur best heard over the left sternal border in the second intercostal space. ECG shows ST elevation in\nleads II, III and aVF. A CXR is remarkable for a widened mediastinum. Which one of the following is the most appropriate management?","options":{"A":"Give alteplase.","B":"Give aspirin, intravenous morphine, and beta blockers.","C":"Give morphine and beta blockers and arrange for emergency trans-esophageal sonography.","D":"Refer the patient to cardiology clinic.","E":"Arrange for emergency angiography."},"source_answer":"C","source_explanation":"The clinical findings of abrupt chest pain radiating to back and a widened mediastinum on CXR are consistent with diagnosis aortic\ndissection. The diastolic murmur signifies involvement of the proximal aorta resulting in aortic regurgitation and decreased blood flow to the\ncoronary arteries and a consequent myocardial infarction (MI). Thrombolytics (e.g. alteplase) (option A) are absolutely contraindicated when\naortic dissection is suspected.\nAspirin (option B), clopidogrel and other anticoagulation medications are contraindicated as well due to increased risk of deterioration of the\ndissection, which is temporarily stable. The cornerstone of initial therapy in this situation is morphine for pain control (and its partial effect on\nlowering blood pressure) and beta blockers to maintain the systolic blood pressure below 120 mmHg. Trans-esophageal sonography should\nbe emergently performed to confirm the diagnosis.Angiography using CT angiogram (CTA) (option E) is the preferred method if trans-\nesophageal sonography is not available.\n(Option C) Referring the patient to a cardiology clinic while he is in the hopsital and in urgent need for intervention is not an appropriate\noption.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","management","therapy","thrombol"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"75439fdf216e0b47d19b022cd1ef97141453f4a5","duplicate_group_id":"exact-75439fdf216e","duplicate_sources":[{"record_id":"8df547e12bf2e9b1b0a9","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":50,"source_qid":"261"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=exclu