INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5ca5e90281751c3d9ad1','Amedex 2023.pdf','57','Mixed/Unclassified','A 55-year-old man is on heparin after he developed an acute limb ischemia. Which one of the following tests is used for monitoring the
response to anticoagulation therapy with heparin?','{"A":"Fibrinogen level.","B":"Prothrombin time (PT).","C":"INR.","D":"Activated partial thromboplastin time (aPTT).","E":"Bleeding time (BT)."}','D','Activated partial thromboplastin time (aPTT) is used to assess the integrity of the following coagulation pathways:
Intrinsic pathway that includes prekallikrein, high molecular weight kininogen and factors VIII, IX, XI, and XII.
Common pathway including factors II, V, X, and fibrinogen.
aPTT is also used for monitoring the effects of maintenance therapy with heparin. Usually the goal of heparin maintenance therapy is to keep
aPTT level 1.5- 2.5 times above patient’s aPTT baseline. When starting heparin therapy, aPTT is measured 6-hourly until it is within therapeutic
range of 65-100 seconds, and 24 hourly afterwards.
INR is used for monitoring warfarin therapy. It assesses extrinsic coagulation pathway, as does PT. Normal range of PT in an individual not on
blood thinners is 11-13.5 seconds. PT and INR are prolonged if the patient is on warfarin, or deficient in factors II (prothrombin), III, IX, X, or
fibrinogen, or has vitamin K deficiency.
BT is used as a platelet function test with a normal range of 1-9 minutes. It is prolonged if the patient is on antiplatelet medications (aspirin,
clopidogrel), has thrombocytopenia, or in those with platelet aggregation disorders e.g. Von-Willebrand disease. BT is not used routinely
anymore.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"268","duplicate_group_id":"exact-24be86395a21","duplicate_sources":[{"record_id":"5ca5e90281751c3d9ad1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":57,"source_qid":"268"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5ca5e90281751c3d9ad1","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":57,"source_qid":"268","domain_hint":"Mixed/Unclassified","stem":"A 55-year-old man is on heparin after he developed an acute limb ischemia. Which one of the following tests is used for monitoring the\nresponse to anticoagulation therapy with heparin?","options":{"A":"Fibrinogen level.","B":"Prothrombin time (PT).","C":"INR.","D":"Activated partial thromboplastin time (aPTT).","E":"Bleeding time (BT)."},"source_answer":"D","source_explanation":"Activated partial thromboplastin time (aPTT) is used to assess the integrity of the following coagulation pathways:\nIntrinsic pathway that includes prekallikrein, high molecular weight kininogen and factors VIII, IX, XI, and XII.\nCommon pathway including factors II, V, X, and fibrinogen.\naPTT is also used for monitoring the effects of maintenance therapy with heparin. Usually the goal of heparin maintenance therapy is to keep\naPTT level 1.5- 2.5 times above patient’s aPTT baseline. When starting heparin therapy, aPTT is measured 6-hourly until it is within therapeutic\nrange of 65-100 seconds, and 24 hourly afterwards.\nINR is used for monitoring warfarin therapy. It assesses extrinsic coagulation pathway, as does PT. Normal range of PT in an individual not on\nblood thinners is 11-13.5 seconds. PT and INR are prolonged if the patient is on warfarin, or deficient in factors II (prothrombin), III, IX, X, or\nfibrinogen, or has vitamin K deficiency.\nBT is used as a platelet function test with a normal range of 1-9 minutes. It is prolonged if the patient is on antiplatelet medications (aspirin,\nclopidogrel), has thrombocytopenia, or in those with platelet aggregation disorders e.g. Von-Willebrand disease. BT is not used routinely\nanymore.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["anticoag","antiplatelet","therapy","warfarin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"24be86395a21288592286000eb93a0b432134ad0","duplicate_group_id":"exact-24be86395a21","duplicate_sources":[{"record_id":"5ca5e90281751c3d9ad1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":57,"source_qid":"268"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
