INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('5ca5e90281751c3d9ad1','src-v294-687f312c','268','57','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 55-year-old man is on heparin after he developed an acute limb ischemia. Which one of the following tests is used for monitoring the
response to anticoagulation therapy with heparin?',NULL,'D','Activated partial thromboplastin time (aPTT) is used to assess the integrity of the following coagulation pathways:
Intrinsic pathway that includes prekallikrein, high molecular weight kininogen and factors VIII, IX, XI, and XII.
Common pathway including factors II, V, X, and fibrinogen.
aPTT is also used for monitoring the effects of maintenance therapy with heparin. Usually the goal of heparin maintenance therapy is to keep
aPTT level 1.5- 2.5 times above patient’s aPTT baseline. When starting heparin therapy, aPTT is measured 6-hourly until it is within therapeutic
range of 65-100 seconds, and 24 hourly afterwards.
INR is used for monitoring warfarin therapy. It assesses extrinsic coagulation pathway, as does PT. Normal range of PT in an individual not on
blood thinners is 11-13.5 seconds. PT and INR are prolonged if the patient is on warfarin, or deficient in factors II (prothrombin), III, IX, X, or
fibrinogen, or has vitamin K deficiency.
BT is used as a platelet function test with a normal range of 1-9 minutes. It is prolonged if the patient is on antiplatelet medications (aspirin,
clopidogrel), has thrombocytopenia, or in those with platelet aggregation disorders e.g. Von-Willebrand disease. BT is not used routinely
anymore.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"268","duplicate_group_id":"exact-24be86395a21","duplicate_sources":[{"record_id":"5ca5e90281751c3d9ad1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":57,"source_qid":"268"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
