INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('120833d01ba961cb848c','Amedex 2023.pdf','92','Mixed/Unclassified','A 56-year-old Aboriginal Australian man is brought to the Emergency Department of a local hospital with severe chest pain radiating to the left
arm, hypotension, and bradycardia. An ECG confirms ST elevation in leads I, aVL, V5 and V6. Which one of the following fibrinolytic agents
cannot be used for treatment of this patient?','{"A":"Alteplase.","B":"Tenecteplase.","C":"Urokinase.","D":"Streptokinase.","E":"Reteplase."}','D','There is a high prevalence of IgG anti-streptokinase antibody among Aboriginal Australian patients, making this drug an inappropriate option
for thrombolytic therapy in acute ST elevation myocardial infarction in this patient group. This antibody makes treatment with this agent
ineffective.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"23","duplicate_group_id":"exact-ec6a52f32311","duplicate_sources":[{"record_id":"120833d01ba961cb848c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":92,"source_qid":"23"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"120833d01ba961cb848c","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":92,"source_qid":"23","domain_hint":"Mixed/Unclassified","stem":"A 56-year-old Aboriginal Australian man is brought to the Emergency Department of a local hospital with severe chest pain radiating to the left\narm, hypotension, and bradycardia. An ECG confirms ST elevation in leads I, aVL, V5 and V6. Which one of the following fibrinolytic agents\ncannot be used for treatment of this patient?","options":{"A":"Alteplase.","B":"Tenecteplase.","C":"Urokinase.","D":"Streptokinase.","E":"Reteplase."},"source_answer":"D","source_explanation":"There is a high prevalence of IgG anti-streptokinase antibody among Aboriginal Australian patients, making this drug an inappropriate option\nfor thrombolytic therapy in acute ST elevation myocardial infarction in this patient group. This antibody makes treatment with this agent\nineffective.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","fibrinol","therapy","thrombol","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version"