INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5f9850f3de89abaaf3ba','Amedex 2023.pdf','122','Mixed/Unclassified','A 12-year-old boy is brought to the emergency department with loss of consciousness. His blood glucose on arrival is 2.5 mmol/L. His past
medical history is significant for type I diabetes mellitus, for which he is on insulin. Which one of the following is the most appropriate
management?','{"A":"Dextrose 5% intravenously.","B":"Dextrose 10% intravenously.","C":"Dextrose 50% intravenously.","D":"Normal saline.","E":"Oral sweet juice."}','B','In children with type I diabetes mellitus, hypoglycemia is the most common encountered complication. hypoglycemia may lead to seizures
and loss of consciousness.
In childhood (other than neonatal period), hypoglycaemia is defined as a blood glucose level of <2.6 mmol/L. The most appropriate treatment
of severe hypoglycemia when the patient is unconscious and unable to take oral glucose is with a bolus of intravenous dextrose 10%, 2.5 to 5
mL/Kg followed by 0.03 to 0.05 mL/Kg/minute until the patient is stable.
In adults with hypoglycemia, 50% glucose solution is used for treatment of severe hypoglycemia. This solution is not recommended for
children because it can result in serum hyperosmolarity and death.
In a conscious and cooperative child, oral route is preferred.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"521","duplicate_group_id":"exact-ac0a4c9d4773","duplicate_sources":[{"record_id":"5f9850f3de89abaaf3ba","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":122,"source_qid":"521"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"5f9850f3de89abaaf3ba","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":122,"source_qid":"521","domain_hint":"Mixed/Unclassified","stem":"A 12-year-old boy is brought to the emergency department with loss of consciousness. His blood glucose on arrival is 2.5 mmol/L. His past\nmedical history is significant for type I diabetes mellitus, for which he is on insulin. Which one of the following is the most appropriate\nmanagement?","options":{"A":"Dextrose 5% intravenously.","B":"Dextrose 10% intravenously.","C":"Dextrose 50% intravenously.","D":"Normal saline.","E":"Oral sweet juice."},"source_answer":"B","source_explanation":"In children with type I diabetes mellitus, hypoglycemia is the most common encountered complication. hypoglycemia may lead to seizures\nand loss of consciousness.\nIn childhood (other than neonatal period), hypoglycaemia is defined as a blood glucose level of <2.6 mmol/L. The most appropriate treatment\nof severe hypoglycemia when the patient is unconscious and unable to take oral glucose is with a bolus of intravenous dextrose 10%, 2.5 to 5\nmL/Kg followed by 0.03 to 0.05 mL/Kg/minute until the patient is stable.\nIn adults with hypoglycemia, 50% glucose solution is used for treatment 