INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('513cda1c39ba25d70dad','Amedex 2023.pdf','148','Mixed/Unclassified','All of the following options are features of diabetic autonomic neuropathy EXCEPT:','{"A":"Bradycardia.","B":"Urinary retention.","C":"Sexual impotence.","D":"Diarrhea.","E":"Foot ulcers."}','E','Autonomic neuropathy is one of the complications of diabetes mellitus. Diabetic autonomic neuropathy is common and often a debilitating
condition. Clinical manifestations of diabetic autonomic neuropathy include the following:
Skin - dry skin (due to lack of sweating), or excessive sweating in defined areas
Eye - poor dark adaptation, sensitivity to bright lights
Cardiovascular - postural lightheadedness, fainting, orthostatic tachycardia, orthostatic bradycardia and orthostatic hypotension
Urinary - urgency, incontinence, dribbling, and bladder emptying abnormalities
Gastrointestinal - diarrhea, constipation, nausea and vomiting
Sexual - erectile dysfunction and ejaculatory failure in men, loss of ability to reach sexual climax in women
Although foot ulcers, a major source of morbidity in patients with diabetes, are a feature of diabetic neuropathy, it is unrelated to autonomic
dysfunction. Diabetic foot ulcers have a different pathophysiology, mostly including peripheral neuropathy and ischemia from peripheral
vascular disease. Poor resistance against infections is also a contributing factor.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1413","duplicate_group_id":"exact-9e3e593ad870","duplicate_sources":[{"record_id":"513cda1c39ba25d70dad","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":148,"source_qid":"1413"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"513cda1c39ba25d70dad","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":148,"source_qid":"1413","domain_hint":"Mixed/Unclassified","stem":"All of the following options are features of diabetic autonomic neuropathy EXCEPT:","options":{"A":"Bradycardia.","B":"Urinary retention.","C":"Sexual impotence.","D":"Diarrhea.","E":"Foot ulcers."},"source_answer":"E","source_explanation":"Autonomic neuropathy is one of the complications of diabetes mellitus. Diabetic autonomic neuropathy is common and often a debilitating\ncondition. Clinical manifestations of diabetic autonomic neuropathy include the following:\nSkin - dry skin (due to lack of sweating), or excessive sweating in defined areas\nEye - poor dark adaptation, sensitivity to bright lights\nCardiovascular - postural lightheadedness, fainting, orthostatic tachycardia, orthostatic bradycardia and orthostatic hypotension\nUrinary - urgency, incontinence, dribbling, and bladder emptying abnormalities\nGastrointestinal - diarrhea, constipation, nausea and vomiting\nSexual - erectile dysfunction and ejaculatory failure in men, loss of ability to reach sexual climax in women\nAlthough foot ulcers, a major source of morbidity in patients with diabetes, are a feature of diabetic neuropathy, it is unrelated to autonomic\ndysfunction. Diabetic foot ulcers have a different pathophysiology, mostly including peripheral neuropathy and ischemia from peripheral\nvascular disease. Poor resistance against infections is also a contributing factor.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["diabetes"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9e3e593ad87040c0db2bd7746e50b129d633bf2a","duplicate_group_id":"exact-9e3e593ad870","duplicate_sources":[{"record_id":"513cda1c39ba25d70dad","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":148,"source_qid":"1413"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
