INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('513cda1c39ba25d70dad','src-v294-687f312c','1413','148','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','All of the following options are features of diabetic autonomic neuropathy EXCEPT:',NULL,'E','Autonomic neuropathy is one of the complications of diabetes mellitus. Diabetic autonomic neuropathy is common and often a debilitating
condition. Clinical manifestations of diabetic autonomic neuropathy include the following:
Skin - dry skin (due to lack of sweating), or excessive sweating in defined areas
Eye - poor dark adaptation, sensitivity to bright lights
Cardiovascular - postural lightheadedness, fainting, orthostatic tachycardia, orthostatic bradycardia and orthostatic hypotension
Urinary - urgency, incontinence, dribbling, and bladder emptying abnormalities
Gastrointestinal - diarrhea, constipation, nausea and vomiting
Sexual - erectile dysfunction and ejaculatory failure in men, loss of ability to reach sexual climax in women
Although foot ulcers, a major source of morbidity in patients with diabetes, are a feature of diabetic neuropathy, it is unrelated to autonomic
dysfunction. Diabetic foot ulcers have a different pathophysiology, mostly including peripheral neuropathy and ischemia from peripheral
vascular disease. Poor resistance against infections is also a contributing factor.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1413","duplicate_group_id":"exact-9e3e593ad870","duplicate_sources":[{"record_id":"513cda1c39ba25d70dad","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":148,"source_qid":"1413"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
