INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('911f8f37c8d4f448b4b5','Amedex 2023.pdf','174','Mixed/Unclassified','A 37-year-old woman, who underwent thyroidectomy 4 days ago, presents with complaints of tingling of her hands and feet and around her
mouth. Her total calcium level was 2.02 (normal 2.1- 2.6 mmol/L) on discharge. Which one of the following is the best immediate
management of this patient?','{"A":"Intravenous calcium.","B":"Calcium gluconate, orally.","C":"Calcium gluconate and vitamin D, orally.","D":"Diazepam.","E":"Calcitriol."}','A','Every patient with symptomatic hypocalcemia (paresthesia of hands, feet and perioral area are sensory equivalents of tetany) with any
calcium concentration below the reference and those with asymptomatic hypocalcemia, whose total calcium levels have acutely fallen below
1.9 mmol/L are recommended to urgently have calcium replaced intravenously.
Ten to 20ml of 10% calcium gluconate in 50-100 ml of Dextrose 5% should be given intravenously over 10-20 minutes with ECG monitoring.
This can be repeated until the patient is asymptomatic. It should be followed with a calcium gluconate infusion. Calcium chloride can be used
as an alternative to calcium gluconate, but it is more irritating to veins and should only be given via a central line.
If the case was asymptomatic hypocalcemia (with calcium above 1.9 mmol/L) or latent tetany (represented by positive Trousseau and/or
Chvostek sign) oral calcium with or without vitamin D supplementation was the choice.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"98","duplicate_group_id":"exact-83e32fa911e1","duplicate_sources":[{"record_id":"911f8f37c8d4f448b4b5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":174,"source_qid":"98"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"911f8f37c8d4f448b4b5","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":174,"source_qid":"98","domain_hint":"Mixed/Unclassified","stem":"A 37-year-old woman, who underwent thyroidectomy 4 days ago, presents with complaints of tingling of her hands and feet and around her\nmouth. Her total calcium level was 2.02 (normal 2.1- 2.6 mmol/L) on discharge. Which one of the following is the best immediate\nmanagement of this patient?","options":{"A":"Intravenous calcium.","B":"Calcium gluconate, orally.","C":"Calcium gluconate and vitamin D, orally.","D":"Diazepam.","E":"Calcitriol."},"source_answer":"A","source_explanation":"Every patient with symptomatic hypocalcemia (paresthesia of hands, feet and perioral area are sensory equivalents of tetany) with any\ncalcium concentration below the reference and those with asymptomatic hypocalcemia, whose total calcium levels have acutely fallen below\n1.9 mmol/L are recommended to urgently have calcium replaced intravenously.\nTen to 20ml of 10% calcium gluconate in 50-100 ml of Dextrose 5% should be given intravenously over 10-20 minutes with ECG monitoring.\nThis can be repeated until the patient is asymptomatic. It should be followed with a calcium gluconate infusion. Calcium chloride can be used\nas an alternative to calcium gluconate, but it is more irritating to veins and should only be given via a central line.\nIf the case was asymptomatic hypocalcemia (with calcium above 1.9 mmol/L) or latent tetany (represented by positive Trousseau and/or\nChvostek sign) oral calcium with or without vitamin D supplementation was the choice.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","management"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"83e32fa911e1401822a1c687e07de3fa89e1e36a","duplicate_group_id":"exact-83e32fa911e1","duplicate_sources":[{"record_id":"911f8f37c8d4f448b4b5","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":174,"source_qid":"98"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
