INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3f00c50e46dfa803620f','Amedex 2023.pdf','184','Mixed/Unclassified','A 55-year-old woman comes to your clinic because she is concerned about developing osteoporosis after menopause. Which one of the
following is correct regarding prevention of osteoporosis?','{"A":"Bisphosphonates are recommended only for women and just for primary prevention of osteoporosis.","B":"Strontium ranelate is recommended only for treatment of severe osteoporosis in postmenopausal women.","C":"Bisphosphonates are recommended only for women and just for treatment of osteoporosis.","D":"In women with minimal-trauma fractures, bisphosphonates are contraindicated.","E":"Alendronate is the second-line therapy in the treatment of postmenopausal osteoporosis."}','B','Bisphosphonates (e.g. alendronate, residronate, zoledronic acid) can be used in both men and women, not only for primary prevention of
osteoporosis, but also for treatment of established osteoporosis and prevention of more fractures. Bisphosphonates are always first-line
therapy unless contraindicated.
Raloxifene is used in post-menopausal women as the second-line therapy, where bisphosphonates are contraindicated. It can be used for
both prevention and treatment of osteoporosis.
Strontium ranelate is used to treat severe osteoporosis or those with minimal trauma fratures while on adequate dose of bisphosphonates. It
works by increasing bone formation and decreasing bone loss. Myocardial infarction is a worrisome adverse effect that limits the use of this
drug to severe cases of osteoporosis under strict care and surveillance.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"772","duplicate_group_id":"exact-528adb65023d","duplicate_sources":[{"record_id":"3f00c50e46dfa803620f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":184,"source_qid":"772"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"3f00c50e46dfa803620f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":184,"source_qid":"772","domain_hint":"Mixed/Unclassified","stem":"A 55-year-old woman comes to your clinic because she is concerned about developing osteoporosis after menopause. Which one of the\nfollowing is correct regarding prevention of osteoporosis?","options":{"A":"Bisphosphonates are recommended only for women and just for primary prevention of osteoporosis.","B":"Strontium ranelate is recommended only for treatment of severe osteoporosis in postmenopausal women.","C":"Bisphosphonates are recommended only for women and just for treatment of osteoporosis.","D":"In women with minimal-trauma fractures, bisphosphonates are contraindicated.","E":"Alendronate is the second-line therapy in the treatment of postmenopausal osteoporosis."},"source_answer":"B","source_explanation":"Bisphosphonates (e.g. alendronate, residronate, zoledronic acid) can be used in both men and women, not only for primary prevention of\nosteoporosis, but also for treatment of established osteoporosis and prevention of more fractures. Bisphosphonates are always first-line\ntherapy unless contraindicated.\nRaloxifene is used in post-menopausal women a