INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('91bc957e58abd6b4a5a3','Amedex 2023.pdf','247','Mixed/Unclassified','A 41-year-old farmer has presented with a lesion on his right sole. The lesion appeared 4 months ago and has progressively enlarged since then. The lesion is shown in the accompanying photograph. Which one of the following could be the most
likely diagnosis?','{"A":"Neuropathic ulcer.","B":"Malignant melanoma.","C":"Simple nevus.","D":"Pigmentation from heat.","E":"Squamous cell carcinoma."}','B','The size and color of the lesion, the irregularity, and the rapid progression are highly suggestive of malignant melanoma.
(Option A) Neuropathic ulcers occur over pressure points of areas with impaired sensation due to conditions such as diabetes mellitus (the most common cause), syphilis, leprosy, and other neuropathies. They present a completely different picture.
Neuropathic ulcer 
(Option C) The rapid progression, size, and irregularity are inconsistent with melanoma rather than simple nevus as a diagnosis. A simple nevus usually has regular borders, is often unicolor, and does not spread so fast. 
(Option D) Pigmentation from heat, also called ‘erythema ab igne’ is tanning of the skin, where it is chronically exposed to heat.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-8b7eda2b8556","duplicate_sources":[{"record_id":"91bc957e58abd6b4a5a3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":247,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"91bc957e58abd6b4a5a3","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":247,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 41-year-old farmer has presented with a lesion on his right sole. The lesion appeared 4 months ago and has progressively enlarged since then. The lesion is shown in the accompanying photograph. Which one of the following could be the most\nlikely diagnosis?","options":{"A":"Neuropathic ulcer.","B":"Malignant melanoma.","C":"Simple nevus.","D":"Pigmentation from heat.","E":"Squamous cell carcinoma."},"source_answer":"B","source_explanation":"The size and color of the lesion, the irregularity, and the rapid progression are highly suggestive of malignant melanoma.\n(Option A) Neuropathic ulcers occur over pressure points of areas with impaired sensation due to conditions such as diabetes mellitus (the most common cause), syphilis, leprosy, and other neuropathies. They present a completely different picture.\nNeuropathic ulcer \n(Option C) The rapid progression, size, and irregularity are inconsistent with melanoma rather than simple nevus as a diagnosis. A simple nevus usually has regular borders, is often unicolor, and does not spread so fast. \n(Option D) Pigmentation from heat, also called ‘erythema ab igne’ is tanning of the skin, where it is chronically exposed to heat.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["diabetes"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"8b7eda2b855605247729c3b1ead321477337468a","duplicate_group_id":"exact-8b7eda2b8556","duplicate_sources":[{"record_id":"91bc957e58abd6b4a5a3","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":247,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
