INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('706f6b793023a1ef0c4b','Amedex 2023.pdf','265','Mixed/Unclassified','A 32-year-old man is brought to the Emergency Department by ambulance after he sustained a house fire. On examination, the patient is
conscious but in severe distress due to pain. He has voice hoarseness, burns around the neck, and burned nose hair. Which one of the
following is the next best step in management?','{"A":"Intubation.","B":"Oxygen by face mask.","C":"Intravenous morphine for analgesia.","D":"Debridment of the burns and application of topical antibiotics.","E":"Intravenous fluids."}','B','In victims of a close environment burns, smoke and heat inhalation is associated with significant risk of airway obstruction. Any patient with
sooth in the mouth or nose or burns in the face or mouth or around the neck should be monitored very carefully for airway compromise due to
edema. Burn victims should be intubated before edema results in complete airway obstruction.
This patient has hoarseness that indicates airway involvement, and intubation should be considered. In meanwhile he should receive
supplemental oxygen as the most important next step in management while arrangements for intubation are undertaken.
All other options are considered as parts of management, but none takes precedent over oxygenation and intubation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"141","duplicate_group_id":"exact-8287687728cb","duplicate_sources":[{"record_id":"706f6b793023a1ef0c4b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":265,"source_qid":"141"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"706f6b793023a1ef0c4b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":265,"source_qid":"141","domain_hint":"Mixed/Unclassified","stem":"A 32-year-old man is brought to the Emergency Department by ambulance after he sustained a house fire. On examination, the patient is\nconscious but in severe distress due to pain. He has voice hoarseness, burns around the neck, and burned nose hair. Which one of the\nfollowing is the next best step in management?","options":{"A":"Intubation.","B":"Oxygen by face mask.","C":"Intravenous morphine for analgesia.","D":"Debridment of the burns and application of topical antibiotics.","E":"Intravenous fluids."},"source_answer":"B","source_explanation":"In victims of a close environment burns, smoke and heat inhalation is associated with significant risk of airway obstruction. Any patient with\nsooth in the mouth or nose or burns in the face or mouth or around the neck should be monitored very carefully for airway compromise due to\nedema. Burn victims should be intubated before edema results in complete airway obstruction.\nThis patient has hoarseness that indicates airway involvement, and intubation should be considered.