INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f26a1fe666b47452220a','Amedex 2023.pdf','275','Mixed/Unclassified','Eighteen hours after an uneventful cholecystectomy on a 45-year-old woman, she develops a fever and a cough. A chest X-ray (CXR) is
obtained that is shown in the following photograph. Which one of the following is the next best step in management?','{"A":"Chest physiotherapy.","B":"Oral antibiotics.","C":"Intravenous antibiotics.","D":"Intravenous steroids.","E":"Morphine."}','A','Of significance on the CXR, is the loss of the right heart border shadow, indicating collection in the right middle lobe. The onset of symptoms
within the first 24 hours post-operatively, in addition to the CXR findings is consistent with the diagnosis of atelectasis. Atelectasis is common
in abdominal and trans-thoracic procedures. Mucus retention in airways leads to post-obstructive collapse of the distal airways, particularly in
the lower parts of the lung. Pneumonia can complicate atelectasis.
Post-operative atelectasis is managed as follows:
Removal of impacted secretion by percussion and encouraging the patient to actively cough.
Passive postural drainage.
The most important step in management is chest physiotherapy, followed by oxygen supplementation. If the above measures failed, a
catheter can be passed through, guided by bronchoscope, for more vigorous removal of the secretions.
(Options B and C) Antibiotics are not indicated unless fever persists more than 48 hours, suggesting superimposed pulmonary infection
(pneumonia).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-c03294e465a2","duplicate_sources":[{"record_id":"f26a1fe666b47452220a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":275,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"f26a1fe666b47452220a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":275,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"Eighteen hours after an uneventful cholecystectomy on a 45-year-old woman, she develops a fever and a cough. A chest X-ray (CXR) is\nobtained that is shown in the following photograph. Which one of the following is the next best step in management?","options":{"A":"Chest physiotherapy.","B":"Oral antibiotics.","C":"Intravenous antibiotics.","D":"Intravenous steroids.","E":"Morphine."},"source_answer":"A","source_explanation":"Of significance on the CXR, is the loss of the right heart border shadow, indicating collection in the right middle lobe. The onset of symptoms\nwithin the first 24 hours post-operatively, in addition to the CXR findings is consistent with the diagnosis of atelectasis. Atelectasis is common\nin abdominal and trans-thoracic procedures. Mucus retention in airways leads to post-obstructive collapse of the distal airways, particularly in\nthe lower parts of the lung. Pneumonia can complicate atelectasis.\nPost-operative atelectasis is managed as follows:\nRemoval of impacted secretion by percussion and encouraging the patient to actively cough.\nPassive postural drainage.\nThe most important step in management is chest physiotherapy, followed by oxygen supplementation. If the above measures failed, a\ncatheter can be passed through, guided by bronchoscope, for more vigorous removal of the secretions.\n(Options B and C) Antibiotics are not indicated unless fever persists more than 48 hours, suggesting superimposed pulmonary infection\n(pneumonia).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","management","therapy"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"c03294e465a25dad01bcd9826cd6f285142598e4","duplicate_group_id":"exact-c03294e465a2","duplicate_sources":[{"record_id":"f26a1fe666b47452220a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":275,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
