INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('de9dd5b91f9c6bdd0b75','src-v294-687f312c','1706','317','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','Irukandji syndrome could potentially be caused by:',NULL,'D','Irukandji syndrome is a painful, potentially lethal condition caused by certain jellyfish from the Cubozoa class (box jellyfish) species. This
species has a small body (size of a coin) and usually four tentacles. The sting is usually mild and often goes unnoticed by the victim; however,
after 20-30 minutes of the sting, a surge of catecholamine resulting in tachycardia, hypertension, agitation and generalized severe pain and
cramps especially in the abdomen and back. Hypotension and, pulmonary edema, and potentially life-threatening cardiac complications can
follow.
Victims should be transferred to the hospital for:
Analgesia (oral and IV)
Investigation and treatment of cardiac effects (echocardiogram, troponin)
Cardiac monitoring',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1706","duplicate_group_id":"exact-5cd74ac42fb1","duplicate_sources":[{"record_id":"de9dd5b91f9c6bdd0b75","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":317,"source_qid":"1706"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
