INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b0c5ee393d0c89acaae7','Amedex 2023.pdf','381','Mixed/Unclassified','A 25-year-old man is involuntarily admitted to the mental health ward for treatment of psychosis. On physical
examination, he is found to have a 5x5 cm ulcer on the plantar surface of his left foot, requiring wound debridment,
irrigation and intravenous antibiotics. Which one of the following is the most appropriate approach regarding
consent for treatment of his wound?','{"A":"No consent is required as the patient is already involuntarily admitted.","B":"Take consent from the treating psychiatrist.","C":"Take consent from the patient.","D":"Contact the patient''s family for informed consent.","E":"Apply to the mental health tribunal for consent for wound debridment."}','C','Patients who are subject to involuntary treatment under mental health act, may still have capacity to give or decline
consent for a specific healthcare matter not related to their current mental illness (for example the use of antibiotics
for chest infection, or a surgical procedure on the limb). Assessment of the patient’s capacity to make decisions
about every other treatment other than that for the initial problem should be performed in the standard way and
documented appropriately.
If a patient lacks capacity to give consent to health care for a condition unrelated to the current mental illness, the
consent should be sought from a substitute decision maker in the same order as for other patients who are not
legally able to give informed consent. Involuntary treatment order only applies to the current mental health issue and
does not cover other areas of treatment.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"818","duplicate_group_id":"exact-dd8f8b03e774","duplicate_sources":[{"record_id":"b0c5ee393d0c89acaae7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":381,"source_qid":"818"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"b0c5ee393d0c89acaae7","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":381,"source_qid":"818","domain_hint":"Mixed/Unclassified","stem":"A 25-year-old man is involuntarily admitted to the mental health ward for treatment of psychosis. On physical\nexamination, he is found to have a 5x5 cm ulcer on the plantar surface of his left foot, requiring wound debridment,\nirrigation and intravenous antibiotics. Which one of the following is the most appropriate approach regarding\nconsent for treatment of his wound?","options":{"A":"No consent is required as the patient is already involuntarily admitted.","B":"Take consent from the treating psychiatrist.","C":"Take consent from the patient.","D":"Contact the patient''s family for informed consent.","E":"Apply to the mental health tribunal for consent for wound debridment."},"source_answer":"C","source_explanation":"Patients who are subject to involuntary treatment under mental health act, may still have capacity to give or decline\nconsent for a specific healthcare matter not related to their current mental illness (for example the use of antibiotics\nfor chest infection, or a surgical procedure on the limb). Assessment of the patient’s capacity to make decisions\nabout every other 